let _lastLoadedModelUrl: string | null = null

/** Track how many preload requests were initiated vs completed in a batch */
let _preloadBatchTotal = 0
let _preloadBatchDone = 0

/**
 * Synthetic progress animation for when Content-Length is missing
 * Uses asymptotic curve: progress approaches 90% but never reaches it.
 * Gives visual feedback on slow networks where real progress events don't fire.
 */
let _syntheticProgressTimer: any = null
let _syntheticProgressStart = 0
let _hasRealProgress = false

function _startSyntheticProgress(taskId: string = "default") {
    _hasRealProgress = false
    _syntheticProgressStart = performance.now()
    if (_syntheticProgressTimer) cancelAnimationFrame(_syntheticProgressTimer)

    const tick = () => {
        if (_hasRealProgress) return // real progress took over
        const mls =
            typeof window !== "undefined"
                ? (window as any).__modelLoadingState
                : null
        if (!mls || !mls.isLoading || mls.isComplete) return

        // Asymptotic curve: 1 - e^(-t/k), capped at 0.85
        // k=8 means ~63% at 8s, ~78% at 12s, ~85% at 15s — feels natural
        const elapsed = (performance.now() - _syntheticProgressStart) / 1000
        const synthetic = (1 - Math.exp(-elapsed / 8)) * 0.85
        mls.setProgress(taskId, synthetic)
        _syntheticProgressTimer = requestAnimationFrame(tick)
    }

    // Start after 500ms delay — give real progress events a chance to fire first
    setTimeout(() => {
        if (!_hasRealProgress) {
            _syntheticProgressTimer = requestAnimationFrame(tick)
        }
    }, 500)
}

function _stopSyntheticProgress() {
    if (_syntheticProgressTimer) {
        cancelAnimationFrame(_syntheticProgressTimer)
        _syntheticProgressTimer = null
    }
}

export function _clearModelCache() {
    for (const [, cached] of _modelCache) {
        _disposeModelFull(cached.scene)
    }
    _modelCache.clear()
    _preloadInFlight.clear()
    _preloadBatchTotal = 0
    _preloadBatchDone = 0
}

export function _startModelPreload(url: string): Promise<void> {
    if (!url) return Promise.resolve()
    if (_modelCache.has(url)) return Promise.resolve()
    if (_preloadInFlight.has(url)) return _preloadInFlight.get(url)!

    const format = detectFormat(url)

    // Broadcast loading state immediately so splash screen knows to wait
    if (typeof window !== "undefined" && (window as any).__modelLoadingState) {
        const mls = (window as any).__modelLoadingState
        if (!mls.isLoading && !mls.isComplete) {
            mls.setLoading(url)
        }
    }

    // Track batch count
    _preloadBatchTotal++

    // Start synthetic progress animation (gives visual feedback when Content-Length is missing)
    if (_preloadBatchTotal === 1) _startSyntheticProgress(url)

    const promise = new Promise<void>((resolve) => {
        const _checkBatchComplete = () => {
            // When ALL in-flight preloads are done, set progress to 95%
            // but do NOT call setComplete() — that's the load-model effect's job
            // after the model is actually added to the Three.js scene and visible.
            if (
                _preloadInFlight.size === 0 &&
                typeof window !== "undefined" &&
                (window as any).__modelLoadingState
            ) {
                const mls = (window as any).__modelLoadingState
                if (mls.isLoading && !mls.isComplete) {
                    _stopSyntheticProgress()
                    mls.setProgress(url, 0.95)
                }
                // Reset batch counters
                _preloadBatchTotal = 0
                _preloadBatchDone = 0
            }
        }

        const onDone = (object: any, animations?: any[]) => {
            if (!_modelCache.has(url)) {
                // Clean up skinned mesh artifacts before caching so all clones inherit clean state
                _cleanupSkinnedScene(object)
                const safeAnimations = _sanitizeAnimationClipsForObject(
                    object,
                    animations || []
                )
                _modelCache.set(url, {
                    scene: object, // preload owns this instance — no need to clone
                    animations: safeAnimations.map((c) => c.clone()),
                })
            }
            _preloadInFlight.delete(url)
            _preloadBatchDone++
            _checkBatchComplete()
            resolve()
        }

        const onProgress = (event: any) => {
            if (!event.lengthComputable) return
            // Real progress received — kill synthetic animation
            if (!_hasRealProgress) {
                _hasRealProgress = true
                _stopSyntheticProgress()
            }
            const pct = event.loaded / event.total
            if (
                typeof window !== "undefined" &&
                (window as any).__modelLoadingState
            ) {
                // Scale progress across batch: each URL gets an equal share
                const batchTotal = Math.max(_preloadBatchTotal, 1)
                const perUrlShare = 1 / batchTotal
                const overallPct = (_preloadBatchDone + pct) * perUrlShare
                    ; (window as any).__modelLoadingState.setProgress(
                        url,
                        Math.min(pct * 0.95, 0.95)
                    )
            }
        }

        const onErr = (err: any) => {
            console.warn("[Preload] Failed for", url, err)
            _preloadInFlight.delete(url)
            _preloadBatchDone++
            _checkBatchComplete()
            resolve() // resolve anyway — load-model effect will retry or show error
        }

        try {
            if (format === "zip") _loadFromZip(url, onDone, onProgress, onErr)
            else if (format === "fbx")
                getSharedFBXLoader().load(
                    url,
                    (obj) => onDone(obj, obj.animations || []),
                    onProgress,
                    onErr
                )
            else
                getSharedGLTFLoader().load(
                    url,
                    (g) => onDone(g.scene, g.animations),
                    onProgress,
                    onErr
                )
        } catch (err) {
            onErr(err)
        }
    })

    _preloadInFlight.set(url, promise)
    return promise
}

function _upsertImport3DSlot(
    id: string,
    element: HTMLElement | null,
    props: any,
    scrollContainer: HTMLElement | Element | null = null,
    runtimeSettings: any = null
) {
    if (!id) return
    const state = _getImport3DBridgeState()
    const previous = state.slots.get(id)
    const shouldNotify =
        !previous ||
        previous.element !== element ||
        previous.scrollContainer !== scrollContainer
    if (shouldNotify) {
        state.slotRevision = (state.slotRevision || 0) + 1
    }
    const bridgeProps = runtimeSettings
        ? { ...props, __import3DRuntimeSettings: runtimeSettings }
        : props
    state.slots.set(id, {
        id,
        element,
        scrollContainer,
        props: bridgeProps,
        runtimeSettings,
        revision: shouldNotify
            ? state.slotRevision
            : (previous?.revision ?? state.slotRevision),
        updatedAt: Date.now(),
    })
    if (shouldNotify) {
        _emitImport3DBridge()
    }
}

function _runtimeSlotDomId(id: string) {
    return `import3d-slot-${String(id || "slot").replace(/[^a-zA-Z0-9_-]/g, "_")}`
}

function _upsertImport3DLazySlot(
    id: string,
    domId: string,
    element: HTMLElement | null,
    modelUrl: string
) {
    if (typeof window === "undefined" || !id || !element) return

    const win = window as any
    const registry =
        win.__import3DLazySlots ||
        (win.__import3DLazySlots = {
            slots: new Map(),
            revision: 0,
        })

    if (!element.id) element.id = domId

    const previous = registry.slots.get(id)
    registry.slots.set(id, {
        id,
        domId,
        element,
        modelUrl: modelUrl || "",
        mountedAt: previous?.mountedAt || Date.now(),
        updatedAt: Date.now(),
    })
    registry.revision += 1
}

function _removeImport3DLazySlot(id: string) {
    if (typeof window === "undefined" || !id) return

    const registry = (window as any).__import3DLazySlots
    if (registry?.slots?.delete?.(id)) {
        registry.revision = (registry.revision || 0) + 1
    }
}

function _removeImport3DSlot(id: string) {
    if (!id) return
    const state = _getImport3DBridgeState()
    if (state.slots.delete(id)) {
        _emitImport3DBridge()
    }
}

